/**
 * Generated by `bun run stored-shapes` (packages/hub/scripts/stored-shapes.ts)
 * from the types CawCo stores as JSON: never edited by hand. Each schema's
 * output is proved below to be its type exactly.
 */
import {
  BrowserHostKindShape,
  BrowserKeyShape,
  BrowserPortsShape,
  BrowserRelayShape,
  BrowserRowShape,
  BrowserStateShape,
  FleetMcpConfigSchema,
  HarnessConfigKindShape,
  HookEventShape,
  HookHandlerSchema,
  HookMatchTestShape,
  MediaPathShape,
} from "@cawco/core/stored-shapes";
import { z } from "zod";
import type { MediaMeasurement as MediaMeasurementType } from "./browser/media-forwarding";
import type { BrowserRecord as BrowserRecordType } from "./browser/state";
import type {
  FleetHarnessSet as FleetHarnessSetType,
  SetHarnessConfig as SetHarnessConfigType,
  SetHook as SetHookType,
} from "./fleet-harness-set";
import type { FleetMcpSet as FleetMcpSetType } from "./fleet-mcp-set";
import type { FleetPlaceSet as FleetPlaceSetType } from "./fleet-place-set";

const MediaMeasurementShape = z.object({
  at: z.number(),
  endpoint: z.string(),
  media: MediaPathShape,
  socket: z.string(),
});
export const MediaMeasurementSchema: z.ZodType<MediaMeasurementType> =
  MediaMeasurementShape;

const BrowserRecordShape = z.object({
  container: z
    .object({
      address: z.string().optional(),
      adminPassword: z.string(),
      id: z.string(),
      image: z.string(),
      media: MediaPathShape,
      hostRules: z.string().optional(),
      ports: BrowserPortsShape.optional(),
      runtime: z
        .object({ endpoint: z.string(), kind: z.enum(["docker", "podman"]) })
        .optional(),
      stun: z.string().optional(),
      userPassword: z.string(),
      volume: z.string(),
    })
    .optional(),
  host: BrowserHostKindShape,
  key: BrowserKeyShape,
  lastUsedAt: z.number(),
  local: z
    .object({
      bootId: z.string().optional(),
      pid: z.number(),
      procStart: z.string(),
    })
    .optional(),
  name: z.string(),
  relay: BrowserRelayShape.optional(),
  relayExpiresAt: z.number().optional(),
  relayKey: z.string().optional(),
  runtimeAway: z.literal(true).optional(),
  slot: z.number().optional(),
  state: BrowserStateShape,
  takeover: BrowserRowShape.shape.takeover,
  why: z.string().optional(),
});
export const BrowserRecordSchema: z.ZodType<BrowserRecordType> =
  BrowserRecordShape;

const SetHarnessConfigShape = z.object({
  cwd: z.string().optional(),
  entry: z.string().optional(),
  kind: HarnessConfigKindShape,
  name: z.string(),
  settings: z.record(z.string(), z.unknown()).optional(),
});

const SetHookShape = z.object({
  event: HookEventShape,
  handler: HookHandlerSchema,
  id: z.string(),
  matcher: z.string().optional(),
  name: z.string(),
  test: HookMatchTestShape,
});

export const FleetHarnessSetShape = z.object({
  config: z.record(z.string(), SetHarnessConfigShape),
  hooks: z.record(z.string(), SetHookShape),
});

export const FleetMcpSetShape = z.object({
  servers: z.record(z.string(), FleetMcpConfigSchema),
  signedOut: z.array(z.string()),
});

export const FleetPlaceSetShape = z.object({
  config: z.record(z.string(), SetHarnessConfigShape),
  cwd: z.string(),
  hooks: z.record(z.string(), SetHookShape),
  mcp: z.record(z.string(), FleetMcpConfigSchema),
  skills: z.record(z.string(), z.string()),
});

/**
 * Each property, through every level, as a plain object type. `readonly`
 * goes: it says what code may do with a value, not what a record holds.
 */
type Flat<T> = T extends readonly unknown[]
  ? { -readonly [K in keyof T]: Flat<T[K]> }
  : T extends object
    ? { -readonly [K in keyof T]: Flat<T[K]> }
    : T;
/** Whether A and B are the same type, once flattened. */
type Same<A, B> =
  (<T>() => T extends Flat<A> ? 1 : 2) extends <T>() => T extends Flat<B>
    ? 1
    : 2
    ? true
    : false;
/** Compiles only when every proof it is given holds; a call, so nothing need be exported for it. */
const prove = <Proofs extends true[]>(): Proofs | undefined => undefined;

/** Every schema of an exported type, proved against that type. */
prove<
  [
    Same<z.output<typeof MediaMeasurementShape>, MediaMeasurementType>,
    Same<z.output<typeof BrowserRecordShape>, BrowserRecordType>,
    Same<z.output<typeof SetHarnessConfigShape>, SetHarnessConfigType>,
    Same<z.output<typeof SetHookShape>, SetHookType>,
    Same<z.output<typeof FleetHarnessSetShape>, FleetHarnessSetType>,
    Same<z.output<typeof FleetMcpSetShape>, FleetMcpSetType>,
    Same<z.output<typeof FleetPlaceSetShape>, FleetPlaceSetType>,
  ]
>();
